using OpenAI;
using OpenAI.Chat;
using System.ClientModel;

public class OpenAiService
{
    private readonly ChatClient _chatClient;

    public OpenAiService(string apiKey, string model = "gpt-4o-mini")
    {
        // Instantiate dedicated ChatClient for model
        _chatClient = new ChatClient(model, apiKey);
    }

    public async Task<string> GenerateResponseAsync(string systemInstructions, string userPrompt, CancellationToken ct = default)
    {
        var messages = new List<ChatMessage>
        {
            new SystemChatMessage(systemInstructions),
            new UserChatMessage(userPrompt)
        };

        var options = new ChatCompletionOptions
        {
            Temperature = 0.2f,
            MaxOutputTokenCount = 1000,
            FrequencyPenalty = 0.0f,
            PresencePenalty = 0.0f
        };

        ClientResult<ChatCompletion> result = await _chatClient.CompleteChatAsync(messages, options, ct);
        ChatCompletion completion = result.Value;

        // Log token usage metrics
        var usage = completion.Usage;
        Console.WriteLine($"Input Tokens: {usage.InputTokenCount}, Output Tokens: {usage.OutputTokenCount}");

        return completion.Content[0].Text;
    }
}
